SELECT  FROM scheduled_task
WHERE workspace_id = #{workspaceId} AND is_deleted = 0
AND status = #{status}
AND creator_id = #{creatorId}
AND squad_id = #{squadId}
AND name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM scheduled_task WHERE workspace_id = #{workspaceId} AND is_deleted = 0
AND status = #{status}
AND creator_id = #{creatorId}
AND squad_id = #{squadId}
AND name LIKE CONCAT('%', #{keyword}, '%')

SELECT  FROM scheduled_task
WHERE status = 'ACTIVE' AND is_deleted = 0 AND next_fire_at <= #{now}
ORDER BY next_fire_at ASC, id ASC
LIMIT #{limit}
